package io.forgeloop.control.integrations.github;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import io.forgeloop.control.application.*; import io.forgeloop.control.domain.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/github") public class GithubWebhookController { private final GithubWebhookVerifier verifier; private final GithubDeliveryRepository deliveries; private final FeatureRunService runs; private final ObjectMapper json; private final String secret; public GithubWebhookController(GithubWebhookVerifier verifier,GithubDeliveryRepository deliveries,FeatureRunService runs,ObjectMapper json,@Value("${forgeloop.github.webhook-secret:}") String secret){this.verifier=verifier;this.deliveries=deliveries;this.runs=runs;this.json=json;this.secret=secret;} @PostMapping("/webhooks") public ResponseEntity<Void> receive(@RequestHeader("X-GitHub-Delivery") String delivery,@RequestHeader("X-GitHub-Event") String event,@RequestHeader("X-Hub-Signature-256") String signature,@RequestBody String body){if(!verifier.valid(secret,signature,body))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();if(deliveries.existsByDeliveryId(delivery))return ResponseEntity.accepted().build();deliveries.save(new GithubDelivery(delivery,event));if("issues".equals(event)){try{JsonNode root=json.readTree(body);if("opened".equals(root.path("action").asText())&&root.path("issue").path("labels").findValuesAsText("name").contains("forgeloop")){JsonNode issue=root.path("issue");runs.submit(new FeatureSubmission(root.path("repository").path("full_name").asText(),"issue-"+issue.path("number").asText(),issue.path("title").asText(),issue.path("body").asText(),25));}}catch(Exception ex){throw new IllegalArgumentException("Invalid GitHub webhook payload",ex);}}return ResponseEntity.accepted().build();} }
